style.css:
@-moz-document domain("roblox.com") {
/* Background image */
    body {
        background: url("https://i.postimg.cc/59g6wXCY/silver-surfer-all-alone-in-the-universe-for-phones-5120x9216-v0-l4g3781gzxge1-1-1.png") no-repeat center center fixed !important;
        background-size: cover !important;
        color: #fff !important;
    }

    /* Top bar */
    .navbar, .navigation-bar {
        background-color: #000 !important;
        color: #fff !important;
    }

    /* Sidebar */
    .side-nav, .left-nav {
        background-color: #000 !important;
        color: #fff !important;
    }

    /* Main content area transparency */
    .container-main, .content {
        background-color: rgba(0, 0, 0, 0.6) !important;
    }

    /* Text color fixes */
    .content, .text-label, .text, a {
        color: #fff !important;
    }
}
